    jumpin: { go: '뛰어들고', l: '뛰어들', eo: '뛰어들어', eot: '뛰어들었', ryeo: '뛰어들려', gi: '뛰어들기', neun: '뛰어드는' },
    /* 몸을 던지다: 일에·무대에 몸을 던지는 말은 낮춤 표가 watch 로 */
    throw: { go: '몸(?:을)?던지고', l: '몸(?:을)?던질', eo: '몸(?:을)?던져', ryeo: '몸(?:을)?던지려', gi: '몸(?:을)?던지기', neun: '몸(?:을)?던지는' },
