    eoL: '버리|버릴|버린|버려야|버렸으면|야겠|야지|야해|야돼|야되|야할|야만|드릴|드려야',   // 나를 지워 버리고 싶다 · 나를 없애야 해 · 나를 지워 드릴게요(놓아도 돼·지워도 돼는 아님)
    eoW: '버리고싶|버리고파|버리고프|버릴래|버릴까|버리고말|줄게|줄께|줘야|야겠|야지|드릴',
    eot: '으면|음(?=좋|하|해|싶|함)',                                       // 죽었으면 · 죽었음 좋겠다
    ryeo: '고|는|해|하|합|함|했|구|면|니|다(?!니)',   // 6번째: 죽으려 합니다(글말 높임) · 먹으려 했어요
    ryeop: '니|디|네|지|나', ryeon: '다|대|단|데',      // 6번째: 죽으렵니다 · 사라지련다(STEM_RULES 가 ryeo 에서 만든다)
    gyet2: '(?=습니다|습니당|사옵|사와|소(?![가-힣]))',
    ge: '(?!되|됐|돼|생|두|둬|놔|했|한|만들|하지|말|해|끔|끝|하|된|될|요)',
    peo: '버리|버릴|버린|버림|버려야|버렸|야겠|야지|야제|야할|야돼|야해',
    peot: '',
    pmyeon: '(?:사람도|사람이|진짜|정말|바로|확실히|그냥|다|몇분만에|몇시간만에)*(?:죽|사망|즉사|숨지|안깨|못깨|의식)',                                   // 죽으려고 · 죽으려는 · 죽으려다 말았어(5번째: 멈춘 시도)
    jin: '(?=진(?:않|안))',                                                 // 죽진 않을 거야(③이 부정으로)
    jineg: '(?=(?:도|는|가)?(?:않|안))',                                    // 자해하지 않을(③이 부정으로)
    /* 죽으면 편할까 · 죽으면 모든 게 해결될까 · 죽으면 안 돼? · 나 죽으면 화장해 줘(유언 꼴) */
    /* 2026-11-14 4번째 수정: 죽으면 돼 · 죽으면 되잖아 · 죽으면 그만이야 */
    myeon: '(?:다|모두|모든게|모든것이|모든것|전부|이)?(?:편|나을|낫|좋|행복|끝|해결|슬퍼|누가(?:슬퍼|울|알|기억|신경)|아무도|다들|안돼|안되|안될|어떨|어때)|화장|장례|유골|뿌려|묻어|태워|부탁|챙겨|돌봐|슬퍼하지|울지|' +
      '돼|되잖|되지|된다|될거|될것|되겠|되는거|되는데|그만',
    /* 뛰어내리면·자해하면 × 편해질까·다 끝나겠지·마음이 좀 편해질까·죽을까('뛰어내리면 안 돼'·'자해하면 흉터 남아요'는 아님) */
    myeon2: '(?:다|모두|모든게|모든것이|전부|마음이|기분이|좀|조금|다들|정말|진짜|그냥|내가|나)*(?:편|나을|낫|좋아|좋을|좋겠|행복|끝|해결|후련|시원|덜|풀릴|풀리|괜찮아|사라질|잊|죽|어떨|어때|아플|아파|아프|고통|안아프|덜아프|즉사)',   // 6번째: 뛰어내리면 아플까
    geodeun: '',                                                           // 나 죽거든 화장해 줘
    gi: '로|마렵|싫',                                                      // 죽기로 했어 · 뒤지기 마렵다 · 사라지기 싫어(③이 부정으로: watch)
    gijeon: '전|직전',                                                     // 자살을 하기 전에 (연락할게)
    /* 죽는 게 답 · 죽는 편이 나아 · 죽는 수밖에 · 죽는 법 · 죽는 상상을 해 · 죽는 게 자꾸 생각나 · 나를 끄는 것뿐 */
    neun: '(?:게|편이|쪽이)(?:더)?' + BENEF + '?(?:나|낫|편|좋|답|맞|소원|최선|정답)|게(?:자꾸|계속|요즘|자주|매일)?생각나|거(?:자꾸|계속)?생각나|거(?:나|낫|밖에|말고|답|소원)|것(?:밖에|말고)|것뿐|거뿐|수밖에|길밖에|법|방법|약|상상',
    /* 사라지는 게 나아 · 사라지는 편이 낫겠어 · 조용히 사라지는 법('환청 없어지는 약'은 아님. 앞 낱말이 증상·사물이면 낮춤 표가 지우고, 맨 명사면 watch) */
    vneun: '(?:게|편이|쪽이)(?:더)?' + BENEF + '?(?:나|낫|편|좋|답|맞|최선)|거(?:나|낫|밖에|답)|상상|방법|법',
    /* 2026-11-14 4번째 수정: 지금 하고 있음·고백(자해를 하고 있어요 · 자해하는데 멈추고 싶어 · 자해한다고 말해야 할까). 남 주어·정보 꼴은 낮춤 표가 watch 로 */
    did: '했|함|해버렸|해버림|해서|하는중|시작했|시작함|중이|해봤|해봄|해본적|하고있|하는데|하는거|하는걸|하는게|한다고|한다는|하고살|하면서|하며|해왔|하게됐|하게되|하곤|해요|중|해',   // 끝의 '해요·중·해'는 원문 낱말이 끝날 때만(낮춤 표)
    ja: '(?!사자|살자|고(?:공부|일|노력|달려|달리|매달|덤|싸우|뛰|연습|버티|버텨|열심))',   // 죽자 · 뒤지자 ('죽자 사자 매달려'·'죽자고 공부했어'는 아님)
