  /* 긴 글(2026-11-14 4번째 수정): 예전에는 앞 500자만 봐서 긴 사연 끝의 "사실 죽고 싶어"를 놓쳤다. 이제 500자 창을 400자씩 밀며(100자 겹침:
     한 말이 창 경계에 걸려도 어느 한 창에는 통째로 든다) 모두 보고 가장 무거운 등급을 고른다. 창 머리·꼬리는 띄어쓰기 자리에 맞춘다.
     한 창은 0.1~0.5ms 라 글자 수에 비례해 늘고, 10,000자가 넘는 글은 앞 5,000자와 끝 5,000자만 본다(P6). high 와 타해가 함께 나오면 멈춘다 */
